import{_ as t,o as a,c as o,a3 as d}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"API overview","description":"","frontmatter":{},"headers":[],"relativePath":"dev/api/overview.md","filePath":"dev/api/overview.md"}'),r={name:"dev/api/overview.md"};function n(i,e,c,s,h,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="api-overview" tabindex="-1">API overview <a class="header-anchor" href="#api-overview" aria-label="Permalink to &quot;API overview&quot;">​</a></h1><p>Almost all endpoints are under <code>/api/v1</code>. The exception is <strong>Billing</strong> plans and center subscriptions, which live under <code>/api/admin/*</code> and <code>/api/center/*</code> (see <a href="./../domain/billing">Billing</a>). The exact request and response of every endpoint is in the <a href="/docs" target="_self">endpoint reference</a> (Scribe), generated from the code.</p><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Rule</th></tr></thead><tbody><tr><td>Format</td><td>JSON in, JSON out. Resources wrap their payload in <code>data</code>; lists add <code>meta</code> for pagination.</td></tr><tr><td>Errors</td><td>JSON for <code>api/*</code> and any request that expects JSON. Validation errors are 422 with an <code>errors</code> object.</td></tr><tr><td>Language</td><td>Send <code>Accept-Language: en</code> or <code>ar</code> on client browse endpoints. Translatable fields return the requested language.</td></tr><tr><td>Money</td><td>Integer <strong>halalas</strong>. <code>15000</code> is 150.00 SAR.</td></tr><tr><td>Dates</td><td>UTC, ISO 8601. Weekdays use <code>0 = Sunday</code>.</td></tr><tr><td>Prices shown to clients</td><td><code>start_price</code> (lowest option) and <code>display_price</code> (<code>null</code> or <code>{original, discounted, discount_amount, badge}</code>)</td></tr><tr><td>Booking errors</td><td>422 with a stable <code>reason</code> key. See <a href="./../domain/reservations">Reservations</a>.</td></tr></tbody></table><h2 id="surfaces" tabindex="-1">Surfaces <a class="header-anchor" href="#surfaces" aria-label="Permalink to &quot;Surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prefix</th><th>Actor</th></tr></thead><tbody><tr><td><code>clients/*</code></td><td>Client app</td></tr><tr><td><code>centers/*</code></td><td>Center dashboard and app</td></tr><tr><td><code>admin/*</code></td><td>Admin panel</td></tr></tbody></table><p>See <a href="./../architecture/api-surfaces">API surfaces and guards</a>.</p><h2 id="documenting-a-change" tabindex="-1">Documenting a change <a class="header-anchor" href="#documenting-a-change" aria-label="Permalink to &quot;Documenting a change&quot;">​</a></h2><p>Controllers and resources carry Scribe attributes. When a response changes, update <code>#[ResponseField]</code> and <code>#[Endpoint]</code>, then regenerate with <code>php artisan scribe:generate</code>. Behaviour changes also go in these guides; see <a href="./../conventions/documentation">Keeping these docs current</a>.</p>',9)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
